WITH br AS MATERIALIZED ( SELECT r.id AS run , r.about AS about , b.pos AS p0 , ( SELECT min ( pos ) FROM seq WHERE run = r.id AND pos > b.pos AND gate IN ( 68 , 147 ) ) AS pc , ( SELECT min ( pos ) FROM seq WHERE run = r.id AND pos > b.pos AND gate = 147 ) AS pe FROM node n JOIN run r ON r.id = n.run JOIN seq b ON b.run = r.id AND b.gate = 143 WHERE n.gate = 924 AND r.kind = 3 AND r.arrival IN ( 7 , 443 ) ) , kb AS MATERIALIZED ( SELECT br.run , br.about , br.pc , br.pe , k.gate AS kind FROM br JOIN label k ON k.symbol = ( CASE ( SELECT group_concat ( l3.symbol , ' ' ) FROM ( SELECT l2.symbol FROM seq s2 JOIN label l2 ON l2.gate = s2.gate WHERE s2.run = br.run AND s2.pos > br.p0 AND s2.pos < br.pc AND s2.gate <> 3 ORDER BY s2.pos ) l3 ) WHEN 'syn' THEN 'like' WHEN 'synonyms' THEN 'like' WHEN 'ant' THEN 'opposite' WHEN 'antonym' THEN 'opposite' WHEN 'antonyms' THEN 'opposite' WHEN 'hypernym' THEN 'is' WHEN 'instance hypernym' THEN 'is' WHEN 'hypernyms' THEN 'is' WHEN 'hyponym' THEN 'includes' WHEN 'instance hyponym' THEN 'includes' WHEN 'hyponyms' THEN 'includes' WHEN 'troponyms' THEN 'includes' WHEN 'part holonym' THEN 'part' WHEN 'substance holonym' THEN 'part' WHEN 'holonyms' THEN 'part' WHEN 'part meronym' THEN 'has' WHEN 'member meronym' THEN 'has' WHEN 'substance meronym' THEN 'has' WHEN 'meronyms' THEN 'has' WHEN 'member holonym' THEN 'member' WHEN 'similar to' THEN 'similar' WHEN 'also see' THEN 'similar' WHEN 'verb group' THEN 'similar' WHEN 'coordinate terms' THEN 'similar' WHEN 'derivationally related form' THEN 'derived' WHEN 'derived' THEN 'derived' WHEN 'pertainym' THEN 'derived' WHEN 'related' THEN 'related' WHEN 'entailment' THEN 'implies' WHEN 'cause' THEN 'causes' WHEN 'attribute' THEN 'property' WHEN 'domain category' THEN 'topic' WHEN 'topics' THEN 'topic' WHEN 'member of domain category' THEN 'topic' WHEN 'domain region' THEN 'context' WHEN 'member of domain region' THEN 'context' WHEN 'domain usage' THEN 'use' WHEN 'member of domain usage' THEN 'use' WHEN 'participle of' THEN 'past' WHEN 'alternative forms' THEN 'alias' END ) AND k.symbol IS NOT NULL WHERE br.pe IS NOT NULL AND ( SELECT gate FROM seq WHERE run = br.run AND pos = br.pc ) = 68 ) SELECT count ( * ) , count ( DISTINCT kb.kind ) FROM kb JOIN seq t ON t.run = kb.run AND t.pos > kb.pc AND t.pos < kb.pe JOIN label lt ON lt.gate = t.gate WHERE lt.symbol GLOB '[A-Za-z]*' AND t.gate <> kb.about AND coalesce ( nullif ( ( SELECT gate FROM seq WHERE run = kb.run AND pos = t.pos - 1 ) , 3 ) , ( SELECT gate FROM seq WHERE run = kb.run AND pos = t.pos - 2 ) ) IN ( 173 , 68 , 45 , 38 ) AND coalesce ( nullif ( ( SELECT gate FROM seq WHERE run = kb.run AND pos = t.pos + 1 ) , 3 ) , ( SELECT gate FROM seq WHERE run = kb.run AND pos = t.pos + 2 ) ) IN ( 177 , 45 , 147 , 38 )